import java.io.*;
import java.util.*;

public class Main {
    static final int INF = 1_000_000_000;
    static final int NINF = -1_000_000_000;

    static int N, K;
    static int[] head, to, nxt;
    static int edgeIdx;
    static int[] parent, order;
    static int[] maxDist, minDist;

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        K = fs.nextInt();

        head = new int[N];
        Arrays.fill(head, -1);
        to = new int[2 * (N - 1)];
        nxt = new int[2 * (N - 1)];

        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            add(a, b);
            add(b, a);
        }

        parent = new int[N];
        order = new int[N];
        buildOrder();

        maxDist = new int[N];
        minDist = new int[N];

        int lo = 0, hi = N;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (can(mid)) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }

        System.out.println(lo);
    }

    static void add(int a, int b) {
        to[edgeIdx] = b;
        nxt[edgeIdx] = head[a];
        head[a] = edgeIdx++;
    }

    static void buildOrder() {
        int cnt = 0;
        order[cnt++] = 0;
        parent[0] = -1;

        for (int i = 0; i < cnt; i++) {
            int u = order[i];
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (v == parent[u]) continue;
                parent[v] = u;
                order[cnt++] = v;
            }
        }
    }

    static boolean can(int R) {
        Arrays.fill(maxDist, 0);
        Arrays.fill(minDist, INF);

        int centers = 0;

        for (int i = N - 1; i >= 0; i--) {
            int u = order[i];
            int max = maxDist[u];
            int min = minDist[u];

            if (min != INF && max + min <= R) {
                max = NINF;
            }

            if (max == R) {
                centers++;
                if (centers > K) return false;
                min = 0;
                max = NINF;
            }

            int p = parent[u];
            if (p != -1) {
                if (max != NINF) {
                    int val = max + 1;
                    if (val > maxDist[p]) maxDist[p] = val;
                }
                if (min != INF) {
                    int val = min + 1;
                    if (val < minDist[p]) minDist[p] = val;
                }
            } else {
                if (max >= 0) {
                    centers++;
                    if (centers > K) return false;
                }
            }
        }

        return centers <= K;
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            while ((c = read()) <= ' ' && c != -1) {}
            if (c == -1) return -1;

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }

            return val * sign;
        }
    }
}
